{
  "market_version": 1,
  "name": "官方扩展",
  "description": "Persona 官方维护的扩展。",
  "extensions": [
    {
      "manifest": {
        "manifest_version": 1,
        "id": "larkx",
        "name": "飞书（LarkAgentX）",
        "version": "0.4.1",
        "description": "用 LarkAgentX 以你本人的身份接飞书：扫码登录，全部消息进收件箱和知识库，经手机确认后以你的身份发送；在任意会话里以配置的触发前缀（默认 /agent）或 @自己交给助手。走逆向的网页版协议，不是官方接口。",
        "publisher": "nwverse",
        "homepage": "https://github.com/cv-cat/LarkAgentX",
        "engines": {
          "plugin_protocol": 1
        },
        "runtime": {
          "command": "bin/larkx"
        },
        "activation_events": [
          "on_startup"
        ],
        "contributes": {
          "connectors": [
            {
              "id": "larkx",
              "name": "飞书（LarkAgentX）",
              "capabilities": [
                "status",
                "tools",
                "actions",
                "events",
                "inbox",
                "archive",
                "login",
                "threads",
                "fallback"
              ],
              "confirm_always": [
                "larkx_*"
              ],
              "poll_seconds": 60,
              "kinds": [
                "dm",
                "mention",
                "group"
              ],
              "kind_descriptions": {
                "dm": "飞书私聊：对方发来消息，用户最后没有回复。",
                "mention": "飞书群里有人 @ 了用户，用户之后没有回复。",
                "group": "飞书群里的新消息，没有 @ 用户。"
              }
            }
          ],
          "assistant": [
            {
              "id": "larkx",
              "instructions": "assistant/instructions.md"
            }
          ],
          "channel": [
            {
              "id": "larkx",
              "name": "飞书 /agent",
              "kind": "im",
              "connector": "larkx",
              "description": "在任意飞书会话里以配置的触发前缀（默认 /agent，如「/agent 要做的事」）发消息，或在本人消息里 @自己，交给助手；助手以你的身份回复在那条消息下面，末尾标明 AI 代答。群里每个话题各用一段助手对话。打开「推送也发到这里」或「同步主对话」后，这些消息只发到你和自己的飞书私聊，不进群。",
              "capabilities": {
                "format": "plain",
                "max_text": 4000,
                "asks": "none",
                "threads": true,
                "push": true
              }
            }
          ]
        },
        "configuration": {
          "type": "object",
          "properties": {
            "region": {
              "type": "string",
              "title": "站点",
              "description": "改了要重新扫码：登录凭据只对所属站点有效。",
              "default": "feishu",
              "oneOf": [
                {
                  "const": "feishu",
                  "title": "飞书"
                },
                {
                  "const": "lark",
                  "title": "Lark（国际版）"
                }
              ]
            },
            "triage_rules": {
              "type": "string",
              "title": "分拣规则",
              "description": "用你自己的话写飞书消息怎么分拣，比如「直属领导的私聊都要处理」「某某群只看 @ 我的」。留空用 hub 的全局规则。",
              "maxLength": 4000,
              "default": ""
            },
            "agent_prefix": {
              "type": "string",
              "title": "/agent 触发前缀",
              "description": "在飞书会话里以这个前缀发消息给助手（默认 /agent，不区分大小写，后面跟空格、冒号或换行）。必须以 / 开头（不能是 //），2–32 个字符，不能包含空白、控制字符或冒号；留空或不合法时回退默认 /agent。",
              "maxLength": 32,
              "default": "/agent"
            },
            "inbox_triage_chats": {
              "type": "array",
              "title": "分拣普通群消息",
              "description": "填写 larkx_chats 返回的群 ID。这些群里没有 @ 你的消息也按收件箱规则分拣，即使群已静音。模型不可用时归为噪声。",
              "items": {
                "type": "string"
              },
              "default": []
            },
            "agent_reply_suffix": {
              "type": "string",
              "title": "/agent 回复末尾",
              "description": "助手以你的身份回复触发请求（配置的触发前缀，默认 /agent，或 @自己）时加在末尾、标明 AI 代答的一句话。留空或不到 4 个字时用默认的这句，不能去掉。你自己发的消息以这句结尾时不会再次触发助手。",
              "maxLength": 100,
              "default": "🤖 AI 代答，仅供参考"
            },
            "agent_mention": {
              "type": "boolean",
              "title": "@自己唤起助手",
              "description": "默认开启。本人发的消息里用飞书 at 标签 @登录账号本人，也交给助手，请求中去掉这个 @；规则和触发前缀一致，只认本人发的新鲜消息，别人 @你、助手自己的回复都不算。只 @自己没有内容时结合上下文处理。关闭后仅保留所配置的触发前缀（默认 /agent）触发。",
              "default": true
            },
            "agent_group_topics": {
              "type": "boolean",
              "title": "群话题各开对话",
              "description": "默认开启。在旧版路由下，群里不在话题里的助手请求（配置的触发前缀，默认 /agent，或 @自己）开一段新的助手对话，之后在它的话题里发的请求接着这段对话；开启实验性功能 integrations_v2 后，由频道的对话路由模式（thread_mode）决定（例如「按群与话题」会把群内非话题消息归并到同一群对话，在回复开启的话题里追问则单独建话题对话；默认模式全部进频道目标），此开关仅用于关闭群与话题分对话。私聊里的请求仍进这个频道的对话（默认主对话）。关闭后群里的也都进那段对话。",
              "default": true
            },
            "command_hooks": {
              "type": "array",
              "title": "/命令 Hook",
              "description": "每项一个命令，比如 /todo、/note。本人发的、以这些命令开头的新鲜消息不交给助手，改为签名 POST 到下面的 Hook 地址；规则和 /agent 一致，别人发的、历史消息、AI 代答都不算，每条消息只发一次。/agent 留给助手，不能用。留空就不开。",
              "items": {
                "type": "string",
                "pattern": "^/[A-Za-z0-9][A-Za-z0-9_-]{0,31}$"
              },
              "maxItems": 20,
              "uniqueItems": true,
              "default": []
            },
            "command_hook_url": {
              "type": "string",
              "title": "Hook 地址",
              "description": "接收 /命令 的 https 地址；同一台机器上的服务可以写 http://127.0.0.1:端口、http://localhost:端口 或 http://[::1]:端口（沙盒里会自动改成 host.persona.internal）。不跟随重定向。没填时 /命令 Hook 不生效。",
              "format": "uri",
              "maxLength": 2000
            },
            "command_hook_context": {
              "type": "integer",
              "title": "Hook 附带上文",
              "description": "随 Hook 一起发出这个会话里命令之前的几条消息，0 到 20，默认 0 不带。上文里可能有别人的消息，只会发到你自己填的 Hook 地址。",
              "default": 0,
              "minimum": 0,
              "maximum": 20
            },
            "command_hook_quote": {
              "type": "boolean",
              "title": "Hook 附带引用",
              "description": "默认开启。命令是回复某条消息时，随 Hook 一起发出被回复的那条消息。",
              "default": true
            }
          }
        },
        "secrets": [
          {
            "name": "command_hook_secret",
            "title": "Hook 签名密钥",
            "description": "填了之后每次 Hook 请求都带 X-Larkx-Signature: sha256=<HMAC-SHA256(密钥, 时间戳.请求体) 的十六进制>，时间戳在 X-Larkx-Timestamp 里；接收方用它确认请求来自这里。留空不签名。",
            "required": false
          }
        ],
        "permissions": {
          "network": [
            "*.feishu.cn",
            "*.larksuite.com",
            "*.larkoffice.com",
            "codeload.github.com",
            "pypi.org",
            "files.pythonhosted.org",
            "config:command_hook_url",
            "host.persona.internal"
          ]
        }
      },
      "tags": [
        "飞书",
        "消息"
      ],
      "icon": "assets/icon.png",
      "packages": [
        {
          "url": "oci:ghcr.io/nwverse/persona-extensions/larkx@sha256:23d73f7368d9f38c6205053711f3b5c7e46375e8e054e2f7eca6a26bd8781ab6",
          "sha256": "4f01216bcb3e9c9114035f3c7fd6ad3e31e75793334c9b96a91eaa4bae5ac317",
          "size": 74224
        }
      ],
      "icon_url": "https://raw.githubusercontent.com/nwverse/persona-extensions/271b23eabee00c6f618acebaee0eeb7b3a6a2aca/extensions/larkx/assets/icon.png",
      "downloads": 1378
    },
    {
      "manifest": {
        "manifest_version": 1,
        "id": "agent-bypass-allow",
        "name": "Bypass 自动允许",
        "version": "0.2.36",
        "description": "Claude Code 或 Antigravity CLI（agy）开着 bypass 模式（Claude Code 的 bypassPermissions / --dangerously-skip-permissions，agy 的 always-proceed）时，有些调用仍会弹确认框（如读工作目录外的文件、开子 Agent、某些命令），无人值守的 Agent 就卡在「在等你」。在你选的电脑上给 Claude Code 和 agy 装一个本地 hook：只在会话是 bypass 模式时，自动允许命令执行（Bash / run_command）、只读工具（Read、Glob、Grep、LS、NotebookRead 等）和子 Agent。删除、覆盖数据的命令，目标都在临时目录或工作目录里（/tmp、会话的工作目录、~/ag-work、~/wt、Claude Code 的 worktree 等）时直接放行，其余的仍然问你；打开「删除和覆盖也自动允许」可放行其他删除、覆盖，但删除根目录、家目录或其上级目录，以及动态选择的可执行命令、zsh 的求值展开，仍保留确认。force push、改权限的命令，写文件、Workflow 和 MCP 工具，以及你自己配的 ask / deny 规则，始终问你。每次自动允许都记一条（命令截断、去掉密钥）。别的模式照常问你。另有一个默认关的开关「Persona 助手对话的文件写入也自动允许」：打开后，Persona 的主对话和主管对话用 Write、Edit 写白名单目录（默认 ~/.jarvis/assistant 和 ~/.persona/assistant）里的文件时也直接放行，不论什么模式（计划模式除外）；其余照常问你。",
        "publisher": "nwverse",
        "homepage": "https://github.com/nwverse/persona-extensions/tree/main/extensions/agent-bypass-allow",
        "engines": {
          "persona": ">=202611041602",
          "extension_protocol": 1
        },
        "runtime": {
          "command": {
            "linux-amd64": "bin/agent-bypass-allow-linux-amd64",
            "linux-arm64": "bin/agent-bypass-allow-linux-arm64",
            "darwin-arm64": "bin/agent-bypass-allow-darwin-arm64",
            "darwin-amd64": "bin/agent-bypass-allow-darwin-amd64"
          },
          "args": [
            "hub"
          ]
        },
        "node": {
          "command": {
            "linux-amd64": "bin/agent-bypass-allow-linux-amd64",
            "linux-arm64": "bin/agent-bypass-allow-linux-arm64",
            "darwin-arm64": "bin/agent-bypass-allow-darwin-arm64",
            "darwin-amd64": "bin/agent-bypass-allow-darwin-amd64"
          },
          "args": [
            "node"
          ],
          "machines": "machines",
          "permissions": {
            "files": true
          }
        },
        "contributes": {
          "ui": [
            {
              "id": "log",
              "title": "自动允许记录",
              "placement": "extension_page"
            }
          ]
        },
        "configuration": {
          "type": "object",
          "properties": {
            "machines": {
              "type": "array",
              "title": "在哪些电脑上自动允许",
              "description": "打开的电脑上，Claude Code 的 settings.json 和 Antigravity CLI 的 config/hooks.json 里会装上本地 hook；关掉、停用或卸载扩展时去掉。",
              "items": {
                "type": "string",
                "format": "machine",
                "x-os": [
                  "darwin",
                  "linux"
                ]
              },
              "x-confirm": "这台电脑上 bypass 模式的 Claude Code 与 Antigravity CLI（agy）会话，命令执行、读文件（包括工作目录外的）和开子 Agent 的确认将不再问你、直接执行。删除、覆盖临时目录和工作目录里的东西也直接执行；别处的删除、覆盖，以及 force push、改权限仍然问你。每次都会记录。"
            },
            "allow_destructive": {
              "type": "boolean",
              "title": "删除和覆盖也自动允许",
              "description": "打开后，bypass 模式下其他删除、覆盖数据的 Bash 命令（rm、mv、git reset --hard、写进文件的 > 等）可直接放行，包括家目录下的普通子目录，删掉的可能找不回来。删除根目录、整个家目录或其上级目录（含这些目录的通配目标和已解析的链接路径），动态选择的可执行命令、zsh 求值展开、force push、改权限、格式化磁盘，以及你自己配的 ask / deny 规则仍然问你。关着时，只有目标都在临时目录、工作目录里的删除、覆盖才放行。",
              "default": false
            },
            "config_dirs": {
              "type": "array",
              "title": "Claude Code 配置目录",
              "description": "装 Claude Code hook 的目录，~ 是那台电脑的家目录。用了 CLAUDE_CONFIG_DIR 的把那个目录也加上。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.claude"
              ]
            },
            "agy_dirs": {
              "type": "array",
              "title": "Antigravity CLI 配置目录",
              "description": "装 Antigravity CLI（agy）hook 的目录（写入其中的 config/hooks.json），~ 是那台电脑的家目录。默认 ~/.gemini 不存在时会自动跳过；用了自定义 --gemini-dir 的把那个目录也加上。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.gemini"
              ]
            },
            "assistant_writes": {
              "type": "boolean",
              "title": "Persona 助手对话的文件写入也自动允许",
              "description": "打开后，Persona 的主对话和主管对话（不是 bypass 模式）用 Write、Edit 写下面目录里的文件时直接放行，不再弹卡；计划模式除外。只认 Persona 启动的助手对话，普通 Agent 照常问你。目录里的 .claude、.gemini、.agents、.git 和 .mcp.json 等配置路径，目录外的路径，删除（走 Bash）、MultiEdit、NotebookEdit、联网写入，以及你自己配的 ask / deny 规则，照常问你。助手对话用的配置目录要在上面的配置目录里。",
              "default": false
            },
            "assistant_write_dirs": {
              "type": "array",
              "title": "助手对话可直接写入的目录",
              "description": "打开上一项后，助手对话写这些目录里（含子目录）的文件不再问你。~ 是那台电脑的家目录；经过链接和 .. 走到目录外的不算。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.jarvis/assistant",
                "~/.persona/assistant"
              ]
            }
          }
        }
      },
      "tags": [
        "claude-code",
        "antigravity",
        "agents",
        "permissions"
      ],
      "replaces": "claude-bypass-allow",
      "icon": "assets/icon.png",
      "packages": [
        {
          "url": "oci:ghcr.io/nwverse/persona-extensions/agent-bypass-allow@sha256:d0fe41457aa051aa43afe5a0061cd1722ea97412c9004aa6c3e5219b6a075670",
          "sha256": "a807b01ac3dfaf4c073aa977fe55eea943f141b60194888eb6d9aaa0f6c78b20",
          "size": 13808979
        }
      ],
      "icon_url": "https://raw.githubusercontent.com/nwverse/persona-extensions/271b23eabee00c6f618acebaee0eeb7b3a6a2aca/extensions/agent-bypass-allow/assets/icon.png",
      "downloads": 1287
    },
    {
      "manifest": {
        "manifest_version": 1,
        "id": "disklessly",
        "name": "Disklessly 硬盘空间",
        "version": "0.5.4",
        "description": "看每台电脑的硬盘用了多少，把能自动重新生成的缓存删掉腾地方，把一周没动的 AI 对话（Claude Code、Codex 等）搬到你自己的网盘，要用时再拿回来。「检查」只读取大小，不会删任何东西；真要删之前都会先说清楚删什么、再让你确认；对话要先放进网盘、读回核对无误才删电脑上的那份。能看运行 Persona 的这台电脑，也能看通过远程登录（SSH）连得上的其他电脑。还可以在 Persona 的磁盘占用图里把文件、文件夹和 App 搬到网盘或拿回来，并附带给 AI 助手用的查询和操作工具（disklessly mcp）：只看的直接运行，删除、搬走和改电脑设置都要你在对话里确认。对 Persona 助手说一句「帮我腾点空间」，它会按先后列出能删什么、能腾出多少、有什么风险，问你做哪一步；说一句「帮我找回上周聊购物车结算的那段对话」，它会按描述找出最像的几个对话，你选定后再拿回来。",
        "publisher": "nwverse",
        "homepage": "https://github.com/nwverse/persona-extensions/blob/main/docs/extensions/disklessly.md",
        "engines": {
          "extension_protocol": 1
        },
        "activation_events": [
          "on_startup"
        ],
        "runtime": {
          "command": {
            "linux-amd64": "bin/disklessly-linux-amd64",
            "linux-arm64": "bin/disklessly-linux-arm64",
            "darwin-amd64": "bin/disklessly-darwin-amd64",
            "darwin-arm64": "bin/disklessly-darwin-arm64"
          }
        },
        "contributes": {
          "ui": [
            {
              "id": "disklessly",
              "title": "硬盘空间",
              "placement": "nav_page",
              "icon": "gauge"
            },
            {
              "id": "disklessly-sessions",
              "title": "AI 对话",
              "placement": "nav_page",
              "icon": "chat"
            },
            {
              "id": "disklessly-card",
              "title": "硬盘空间 · 概况",
              "placement": "overview_card",
              "opens": "disklessly"
            }
          ],
          "disk_offload": [
            {
              "id": "disklessly",
              "name": "Disklessly",
              "kinds": [
                "file",
                "dir",
                "app"
              ],
              "restore": true
            }
          ],
          "skills": [
            {
              "id": "disklessly",
              "dir": "skills/disklessly"
            }
          ],
          "prompts": [
            {
              "id": "free-space",
              "kind": "quick",
              "title": "帮我腾点空间",
              "text": "帮我腾点空间：看看哪台电脑的硬盘快满了，按先后列出能删什么、能腾出多少、有什么风险，问我做哪一步。"
            }
          ],
          "mcp_servers": [
            {
              "id": "disklessly",
              "command": "disklessly",
              "env": "PERSONA_DISKLESSLY_BIN",
              "args": [
                "mcp"
              ],
              "requires": [
                "mcp"
              ],
              "allow": [
                "disklessly_machines_status",
                "disklessly_scan",
                "disklessly_history",
                "disklessly_sessions_search",
                "disklessly_sessions_status",
                "disklessly_sessions_find",
                "disklessly_advise"
              ]
            }
          ]
        }
      },
      "tags": [
        "disklessly",
        "硬盘清理",
        "AI 对话",
        "网盘"
      ],
      "icon": "assets/icon.png",
      "packages": [
        {
          "url": "oci:ghcr.io/nwverse/persona-extensions/disklessly@sha256:f2ecba26ef5a50330622289786166aeaf148e797246f7c1c13b56bb38129dbaa",
          "sha256": "cc8d52365ed4c92ef2e8f411eea9f9b6160addacea87c6ef9c876bea95a4736a",
